  ('alternate_lat_pulldown', 1, 'Siéntate en la polea alta y sujeta un agarre en cada mano, con los brazos estirados.'),
  ('alternate_lat_pulldown', 2, 'Fija el pecho alto y los hombros abajo, sin dejar que la espalda se redondee.'),
  ('alternate_lat_pulldown', 3, 'Tira de un lado hasta llevar el codo a la altura de las costillas.'),
  ('alternate_lat_pulldown', 4, 'Devuelve ese brazo con control mientras el otro se mantiene estirado.'),
  ('alternate_lat_pulldown', 5, 'Alterna los lados sin girar el tronco para acompañar el tirón.'),
  ('archer_pull_up', 1, 'Cuélgate de la barra con un agarre más ancho que los hombros.'),
  ('archer_pull_up', 2, 'Tira cargando el peso hacia un lado, llevando el pecho hacia esa mano.'),
  ('archer_pull_up', 3, 'Deja el brazo contrario casi estirado, acompañando sin tirar.'),
  ('archer_pull_up', 4, 'Baja controlado hasta quedar colgado con los dos brazos extendidos.'),
  ('archer_pull_up', 5, 'Repite hacia el otro lado, alternando en cada repetición.'),
  ('assisted_pull_up', 1, 'Elige la asistencia y apoya las rodillas en la plataforma de la máquina.'),
  ('assisted_pull_up', 2, 'Sujeta la barra con las palmas al frente, algo más ancho que los hombros.'),
  ('assisted_pull_up', 3, 'Tira de los codos hacia abajo hasta pasar la barbilla por encima de la barra.'),
  ('assisted_pull_up', 4, 'Baja hasta estirar los codos del todo, sin dejarte caer de golpe.'),
  ('assisted_pull_up', 5, 'Reduce la asistencia cuando completes todas las repeticiones con control.'),
  ('assisted_pull_up_inclined', 1, 'Apoya los pies en la plataforma y deja el cuerpo ligeramente inclinado atrás.'),
  ('assisted_pull_up_inclined', 2, 'Sujeta la barra con las palmas al frente y los brazos estirados.'),
  ('assisted_pull_up_inclined', 3, 'Tira llevando el pecho hacia la barra, con los codos cerca del cuerpo.'),
  ('assisted_pull_up_inclined', 4, 'Aguanta un instante arriba, con los omóplatos juntos.'),
  ('assisted_pull_up_inclined', 5, 'Baja con control hasta recuperar la extensión completa.'),
  ('assisted_standing_chin_up', 1, 'Ajusta la asistencia y sujeta la barra con las palmas hacia ti.'),
  ('assisted_standing_chin_up', 2, 'Apoya un pie en el soporte y deja el cuerpo vertical.'),
  ('assisted_standing_chin_up', 3, 'Tira con los bíceps y la espalda hasta pasar la barbilla por la barra.'),
  ('assisted_standing_chin_up', 4, 'Mantén los codos pegados al tronco durante todo el recorrido.'),
  ('assisted_standing_chin_up', 5, 'Baja despacio hasta estirar los brazos por completo.'),
  ('assisted_standing_pull_up', 1, 'Ajusta la asistencia y sujeta la barra con las palmas al frente.'),
  ('assisted_standing_pull_up', 2, 'Apoya un pie en el soporte y estira los brazos del todo.'),
  ('assisted_standing_pull_up', 3, 'Baja los omóplatos antes de empezar a doblar los codos.'),
  ('assisted_standing_pull_up', 4, 'Tira hasta que la barbilla pase la barra, sin balancear las piernas.'),
  ('assisted_standing_pull_up', 5, 'Desciende controlado hasta la posición colgada.'),
  ('back_lever', 1, 'Cuélgate de la barra con las palmas al frente y las manos al ancho de hombros.'),
  ('back_lever', 2, 'Lleva las rodillas al pecho y pasa las piernas entre los brazos.'),
  ('back_lever', 3, 'Sigue girando hasta quedar boca abajo, con la espalda hacia el suelo.'),
  ('back_lever', 4, 'Estira el cuerpo poco a poco hasta dejarlo horizontal y en línea.'),
  ('back_lever', 5, 'Aguanta el tiempo que puedas sostener sin que la cadera caiga.'),
  ('back_pec_stretch', 1, 'Ponte de pie junto a una pared o un marco de puerta.'),
  ('back_pec_stretch', 2, 'Apoya la palma y el antebrazo en la pared, con el codo a la altura del hombro.'),
  ('back_pec_stretch', 3, 'Gira el tronco despacio hacia el lado contrario.'),
  ('back_pec_stretch', 4, 'Para cuando notes tensión en el pecho, no dolor, y respira.'),
  ('back_pec_stretch', 5, 'Sostén medio minuto y cambia de lado.'),
  ('band_assisted_pull_up', 1, 'Pasa una banda por la barra y mete una rodilla o un pie en el lazo.'),
  ('band_assisted_pull_up', 2, 'Sujeta la barra con las palmas al frente y cuelga con los brazos estirados.'),
  ('band_assisted_pull_up', 3, 'Tira hasta pasar la barbilla por encima de la barra.'),
  ('band_assisted_pull_up', 4, 'Baja con control, dejando que la banda ayude sin lanzarte.'),
  ('band_assisted_pull_up', 5, 'Usa una banda más fina a medida que ganes fuerza.'),
  ('band_close_grip_pulldown', 1, 'Ancla la banda por encima de la cabeza y arrodíllate debajo.'),
  ('band_close_grip_pulldown', 2, 'Sujeta los extremos con las manos juntas y los brazos estirados.'),
  ('band_close_grip_pulldown', 3, 'Tira de los codos hacia las costillas manteniendo el pecho alto.'),
  ('band_close_grip_pulldown', 4, 'Junta los omóplatos al final del recorrido.'),
  ('band_close_grip_pulldown', 5, 'Vuelve arriba despacio, sin dejar que la banda tire de ti.'),
  ('band_underhand_pulldown', 1, 'Ancla la banda arriba y arrodíllate debajo del anclaje.'),
  ('band_underhand_pulldown', 2, 'Sujeta los extremos con las palmas hacia ti, al ancho de los hombros.'),
  ('band_underhand_pulldown', 3, 'Tira hacia el pecho con los codos rozando el tronco.'),
  ('band_underhand_pulldown', 4, 'Aprieta la espalda un instante en el punto más bajo.'),
  ('band_underhand_pulldown', 5, 'Deja que la banda te lleve arriba con control.'),
  ('barbell_incline_row', 1, 'Ajusta un banco inclinado y túmbate boca abajo sobre él.'),
  ('barbell_incline_row', 2, 'Sujeta la barra bajo el banco con las palmas hacia abajo.'),
  ('barbell_incline_row', 3, 'Tira de la barra hacia la parte baja del pecho, con los codos atrás.'),
  ('barbell_incline_row', 4, 'Mantén el pecho apoyado en el banco todo el recorrido.'),
  ('barbell_incline_row', 5, 'Baja hasta estirar los brazos sin soltar la tensión.'),
  ('barbell_pendlay_row', 1, 'Coloca la barra en el suelo y ponte con los pies al ancho de las caderas.'),
  ('barbell_pendlay_row', 2, 'Flexiona la cadera hasta que el tronco quede casi paralelo al suelo.'),
  ('barbell_pendlay_row', 3, 'Sujeta la barra algo más ancho que los hombros, con la espalda recta.'),
  ('barbell_pendlay_row', 4, 'Tira explosivo hasta tocar la parte baja del pecho.'),
  ('barbell_pendlay_row', 5, 'Devuelve la barra al suelo en cada repetición y vuelve a empezar.'),
  ('barbell_pullover', 1, 'Túmbate en el banco con los pies apoyados y la barra sobre el pecho.'),
  ('barbell_pullover', 2, 'Sujétala con las manos al ancho de los hombros y los codos algo doblados.'),
  ('barbell_pullover', 3, 'Lleva la barra por detrás de la cabeza sin arquear la zona lumbar.'),
  ('barbell_pullover', 4, 'Para cuando notes el estiramiento en el dorsal y las costillas.'),
  ('barbell_pullover', 5, 'Devuélvela sobre el pecho tirando con la espalda, no con los brazos.'),
  ('barbell_shrug', 1, 'De pie, sujeta la barra por delante con las palmas hacia el cuerpo.'),
  ('barbell_shrug', 2, 'Deja los brazos estirados y la espalda recta.'),
  ('barbell_shrug', 3, 'Sube los hombros hacia las orejas lo más alto que puedas.'),
  ('barbell_shrug', 4, 'Aguanta un segundo arriba sin girar los hombros.'),
  ('barbell_shrug', 5, 'Baja despacio hasta sentir el estiramiento del trapecio.'),
  ('bodyweight_squatting_row', 1, 'Sujeta un poste o una barra fija a la altura del pecho.'),
  ('bodyweight_squatting_row', 2, 'Baja a media sentadilla dejando los brazos estirados.'),
  ('bodyweight_squatting_row', 3, 'Tira del cuerpo hacia el punto de agarre llevando los codos atrás.'),
  ('bodyweight_squatting_row', 4, 'Mantén el pecho alto y la cadera quieta.'),
  ('bodyweight_squatting_row', 5, 'Vuelve a estirar los brazos con control y repite.'),
  ('cable_incline_pushdown', 1, 'Ponte frente a la polea alta y sujeta la barra con los brazos casi estirados.'),
